const store=$getWorkflowStaticData('global');

if (!store.users) store.users={};
if (!store.jobs) store.jobs=[];

const m=$json.message ?? {};
const text=(m.text ?? '').trim();

const chatId=m.chat?.id;
const telegramId=String(m.from?.id ?? '');

if (!chatId || !telegramId) {
  return [];
}

if (!store.users[telegramId]) {
  store.users[telegramId]={
    telegram_id:telegramId,
    chat_id:chatId,
    username:m.from?.username ?? '',
    first_name:m.from?.first_name ?? '',
    language:'ar-SA',
    voice:'ar-SA-HamedNeural',
    video_aspect:'9:16',

    awaiting:null,

    pending_title:null,
    pending_topic:null,
    pending_duration_seconds:null,
    pending_duration_label:null,
    pending_style:null,
    pending_materials:[],

    created_at:new Date().toISOString()
  };
}

const user=store.users[telegramId];

if (!Array.isArray(user.pending_materials)) {
  user.pending_materials=[];
}

if (
  user.pending_duration_seconds === undefined
) {
  user.pending_duration_seconds=null;
}

if (
  user.pending_duration_label === undefined
) {
  user.pending_duration_label=null;
}

user.chat_id=chatId;
user.username=m.from?.username ?? user.username ?? '';
user.first_name=m.from?.first_name ?? user.first_name ?? '';
user.last_seen_at=new Date().toISOString();


// ========================================================
// MATERIAL DETECTION
// ========================================================

const photos=
  Array.isArray(m.photo)
    ? m.photo
    : [];

let incomingMaterial=null;

if (photos.length) {

  const photo=
    photos[photos.length-1];

  incomingMaterial={
    type:'image',
    file_id:photo.file_id,
    extension:'jpg',
    mime_type:'image/jpeg'
  };

} else if (m.video?.file_id) {

  const name=String(
    m.video.file_name || ''
  );

  const ext=
    name.includes('.')
      ? name.split('.').pop().toLowerCase()
      : 'mp4';

  incomingMaterial={
    type:'video',
    file_id:m.video.file_id,
    extension:ext || 'mp4',
    mime_type:m.video.mime_type || 'video/mp4'
  };

} else if (m.document?.file_id) {

  const mime=String(
    m.document.mime_type || ''
  ).toLowerCase();

  if (
    mime.startsWith('image/') ||
    mime.startsWith('video/')
  ) {

    const name=String(
      m.document.file_name || ''
    );

    let ext=
      name.includes('.')
        ? name.split('.').pop().toLowerCase()
        : '';

    if (!ext) {
      const extensionMap={
        'image/jpeg':'jpg',
        'image/png':'png',
        'video/mp4':'mp4',
        'video/quicktime':'mov'
      };

      ext=
        extensionMap[mime]
        || 'mp4';
    }

    incomingMaterial={
      type:
        mime.startsWith('image/')
          ? 'image'
          : 'video',

      file_id:m.document.file_id,
      extension:ext,
      mime_type:mime
    };
  }
}


// ========================================================
// VISUAL STYLES
// ========================================================

const STYLE_OPTIONS={
  '1':{
    key:'realistic',
    label:'واقعي'
  },
  '2':{
    key:'cartoon',
    label:'كرتوني'
  },
  '3':{
    key:'illustration',
    label:'رسومي / Motion Graphics'
  },
  '4':{
    key:'3d',
    label:'ثلاثي الأبعاد 3D'
  },
  '5':{
    key:'futuristic',
    label:'تقني / مستقبلي'
  },
  '6':{
    key:'auto',
    label:'تلقائي'
  }
};

function resolveStyle(value) {
  const raw=String(value || '')
    .trim()
    .toLowerCase();

  if (STYLE_OPTIONS[raw]) {
    return STYLE_OPTIONS[raw];
  }

  const aliases={
    'واقعي':'1',
    'realistic':'1',

    'كرتوني':'2',
    'كرتون':'2',
    'cartoon':'2',

    'رسومي':'3',
    'رسوم':'3',
    'illustration':'3',
    'motion graphics':'3',

    '3d':'4',
    'ثلاثي الأبعاد':'4',
    'ثلاثي الابعاد':'4',

    'تقني':'5',
    'مستقبلي':'5',
    'futuristic':'5',

    'تلقائي':'6',
    'auto':'6'
  };

  const id=aliases[raw];

  return id
    ? STYLE_OPTIONS[id]
    : null;
}

function styleMenu(prefix='') {
  return `${prefix}🎨 اختر نمط المشاهد:

1️⃣ واقعي
2️⃣ كرتوني
3️⃣ رسومي / Motion Graphics
4️⃣ ثلاثي الأبعاد 3D
5️⃣ تقني / مستقبلي
6️⃣ تلقائي

أرسل الرقم من 1 إلى 6.`;
}


// ========================================================
// VIDEO DURATION
// ========================================================

const DURATION_OPTIONS={
  '1':{
    seconds:30,
    label:'30 ثانية'
  },
  '2':{
    seconds:45,
    label:'45 ثانية'
  },
  '3':{
    seconds:60,
    label:'60 ثانية'
  },
  '4':{
    seconds:90,
    label:'90 ثانية'
  },
  '5':{
    seconds:120,
    label:'دقيقتان'
  },
  '7':{
    seconds:0,
    label:'تلقائي'
  }
};

function resolveDuration(value) {
  const raw=String(value || '')
    .trim()
    .toLowerCase();

  if (DURATION_OPTIONS[raw]) {
    return DURATION_OPTIONS[raw];
  }

  const aliases={
    '30':'1',
    '30 ثانية':'1',

    '45':'2',
    '45 ثانية':'2',

    '60':'3',
    'دقيقة':'3',
    '1 دقيقة':'3',

    '90':'4',
    '90 ثانية':'4',

    '120':'5',
    'دقيقتان':'5',
    '2 دقيقة':'5',

    'تلقائي':'7',
    'auto':'7'
  };

  const id=aliases[raw];

  return id
    ? DURATION_OPTIONS[id]
    : null;
}

function durationMenu(prefix='') {
  return `${prefix}⏱ اختر مدة الفيديو:

1️⃣ 30 ثانية
2️⃣ 45 ثانية
3️⃣ 60 ثانية
4️⃣ 90 ثانية
5️⃣ دقيقتان
6️⃣ مدة مخصصة
7️⃣ تلقائي حسب المحتوى

أرسل الرقم من 1 إلى 7.`;
}

function parseCustomDuration(value) {
  const raw=String(value || '')
    .replace(/[^\d]/g,'');

  const seconds=Number(raw);

  if (
    !Number.isInteger(seconds) ||
    seconds < 15 ||
    seconds > 300
  ) {
    return null;
  }

  return seconds;
}

function estimateScriptSeconds(script) {
  const words=String(script || '')
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .length;

  if (!words) {
    return 0;
  }

  // Conservative estimate for Arabic narration.
  return Math.max(
    1,
    Math.round(words / 2.15)
  );
}


// ========================================================
// COMMON OUTPUT
// ========================================================

let command='';

if (text.startsWith('/')) {
  command=text
    .split(/\s+/)[0]
    .split('@')[0]
    .toLowerCase();
}

let route='reply';
let reply='';

let videoTitle='';
let videoSubject='';
let videoScript='';
let scriptMode='';

let visualStyle='auto';
let visualStyleLabel='تلقائي';

let targetDurationSeconds=0;
let targetDurationLabel='تلقائي';

let taskId='';

let materialFileId='';
let materialExtension='';
let materialMimeType='';

let supplementalMaterials=[];


// ========================================================
// MATERIALS
// ========================================================

if (
  command === '/clean_cache' ||
  text === '🧹 تنظيف الكاش'
) {

  route='cache_cleanup';
  reply='';

} else if (command === '/materials') {

  user.awaiting='materials';
  user.pending_materials=[];

  reply=
`📎 إضافة مواد

أرسل الصور أو الفيديوهات التي تريد استخدامها.

يمكنك إرسال عدة ملفات، واحدًا بعد الآخر.

عند الانتهاء أرسل:
/done`;

} else if (
  !command &&
  incomingMaterial
) {

  route='material_upload';

  materialFileId=
    incomingMaterial.file_id;

  materialExtension=
    incomingMaterial.extension;

  materialMimeType=
    incomingMaterial.mime_type;

  reply='';

} else if (
  command === '/done' &&
  user.awaiting === 'materials'
) {

  user.awaiting=null;

  reply=
`✅ انتهت إضافة المواد.

📎 سيتم التحقق من الملفات الفعلية على السيرفر عند بدء الفيديو.

الآن استخدم:
/script
أو
/video`;

} else if (
  !command &&
  incomingMaterial
) {

  reply=
`📎 لإضافة صورة أو فيديو كمادة مساعدة استخدم أولًا:

/materials`;


// ========================================================
// START
// ========================================================

} else if (command === '/start') {

  user.awaiting=null;
  user.pending_title=null;
  user.pending_topic=null;
  user.pending_duration_seconds=null;
  user.pending_duration_label=null;
  user.pending_style=null;

  reply=
`🎬 Pingoo Video جاهز

/video إنشاء فيديو تلقائي
/script إدخال سكربت يدوي
/materials إضافة صور أو فيديوهات
/clean_cache تنظيف الكاش
/status حالة الطلب
/history السجل
/settings الإعدادات
/cancel إلغاء الطلب`;


// ========================================================
// /VIDEO AUTO
// ========================================================

} else if (command === '/video') {

  videoSubject=text
    .replace(/^\/video(?:@\w+)?/i,'')
    .trim();

  user.pending_title=null;
  user.pending_duration_seconds=null;
  user.pending_duration_label=null;
  user.pending_style=null;

  if (!videoSubject) {

    user.awaiting='video_topic';
    user.pending_topic=null;

    reply=
`🎬 أرسل الآن موضوع الفيديو.

مثال:
فوائد النوم وتأثيره على الدماغ`;

  } else {

    user.pending_topic=videoSubject;
    user.awaiting='video_duration';

    reply=durationMenu(
`✅ تم حفظ الموضوع:
${videoSubject}

`
    );
  }


// ========================================================
// /SCRIPT MANUAL
// ========================================================

} else if (command === '/script') {

  user.pending_title=null;
  user.pending_topic=null;
  user.pending_duration_seconds=null;
  user.pending_duration_label=null;
  user.pending_style=null;

  user.awaiting='manual_title';

  reply=
`✍️ وضع السكربت اليدوي

1️⃣ أرسل الآن عنوان الفيديو.`;

} else if (
  !command &&
  user.awaiting === 'manual_title' &&
  text
) {

  user.pending_title=text;
  user.awaiting='manual_topic';

  reply=
`✅ تم حفظ العنوان:
${text}

2️⃣ أرسل الآن موضوع الفيديو.`;

} else if (
  !command &&
  user.awaiting === 'manual_topic' &&
  text
) {

  user.pending_topic=text;
  user.awaiting='manual_duration';

  reply=durationMenu(
`✅ تم حفظ الموضوع:
${text}

3️⃣ `
  );


// ========================================================
// MANUAL DURATION
// ========================================================

} else if (
  !command &&
  user.awaiting === 'manual_duration' &&
  text
) {

  if (text.trim() === '6') {

    user.awaiting='manual_duration_custom';

    reply=
`⏱ أرسل المدة المطلوبة بالثواني.

الحد الأدنى: 15 ثانية
الحد الأعلى: 300 ثانية

مثال:
75`;

  } else {

    const duration=
      resolveDuration(text);

    if (!duration) {

      reply=durationMenu(
`❌ اختيار المدة غير صحيح.

`
      );

    } else {

      user.pending_duration_seconds=
        duration.seconds;

      user.pending_duration_label=
        duration.label;

      user.awaiting='manual_style';

      reply=styleMenu(
`✅ مدة الفيديو:
${duration.label}

4️⃣ `
      );
    }
  }

} else if (
  !command &&
  user.awaiting === 'manual_duration_custom' &&
  text
) {

  const seconds=
    parseCustomDuration(text);

  if (!seconds) {

    reply=
`❌ المدة غير صحيحة.

أرسل رقمًا بين 15 و300 ثانية.`;

  } else {

    user.pending_duration_seconds=seconds;
    user.pending_duration_label=
      `${seconds} ثانية`;

    user.awaiting='manual_style';

    reply=styleMenu(
`✅ مدة الفيديو المستهدفة:
${seconds} ثانية

4️⃣ `
    );
  }


// ========================================================
// MANUAL STYLE
// ========================================================

} else if (
  !command &&
  user.awaiting === 'manual_style' &&
  text
) {

  const selected=
    resolveStyle(text);

  if (!selected) {

    reply=styleMenu(
`❌ الاختيار غير صحيح.

`
    );

  } else {

    user.pending_style=selected.key;
    user.awaiting='manual_script';

    reply=
`✅ نمط المشاهد:
${selected.label}

5️⃣ أرسل الآن السكربت كاملًا.`;
  }


// ========================================================
// MANUAL SCRIPT
// ========================================================

} else if (
  !command &&
  user.awaiting === 'manual_script' &&
  text
) {

  const target=
    Number(
      user.pending_duration_seconds || 0
    );

  const estimated=
    estimateScriptSeconds(text);

  const tolerance=
    target > 0
      ? Math.max(
          8,
          Math.round(target * 0.25)
        )
      : 0;

  if (
    target > 0 &&
    Math.abs(estimated-target) > tolerance
  ) {

    reply=
`⚠️ السكربت لا يناسب المدة المستهدفة.

⏱ المدة المستهدفة:
${user.pending_duration_label}

📝 المدة المتوقعة للسكربت:
حوالي ${estimated} ثانية

أرسل سكربت أقصر أو أطول ليقترب من المدة المطلوبة.

لن نقوم بقص الكلام أو تسريع الصوت تلقائيًا.`;

  } else {

    videoTitle=String(
      user.pending_title || ''
    ).trim();

    videoSubject=String(
      user.pending_topic || ''
    ).trim();

    const selected=
      Object.values(STYLE_OPTIONS)
        .find(
          s => s.key === user.pending_style
        )
      || STYLE_OPTIONS['6'];

    visualStyle=selected.key;
    visualStyleLabel=selected.label;

    targetDurationSeconds=
      Number(
        user.pending_duration_seconds || 0
      );

    targetDurationLabel=
      user.pending_duration_label
      || 'تلقائي';

    videoScript=text;

    user.awaiting=null;
    user.pending_title=null;
    user.pending_topic=null;
    user.pending_duration_seconds=null;
    user.pending_duration_label=null;
    user.pending_style=null;

    route='video';
    scriptMode='manual';

    reply=
`✅ تم استلام السكربت اليدوي.

🎬 العنوان:
${videoTitle}

📝 الموضوع:
${videoSubject}

⏱ المدة:
${targetDurationLabel}

🎨 نمط المشاهد:
${visualStyleLabel}

جاري إنشاء الفيديو...`;
  }


// ========================================================
// AUTO VIDEO TOPIC
// ========================================================

} else if (
  !command &&
  user.awaiting === 'video_topic' &&
  text
) {

  user.pending_topic=text;
  user.pending_duration_seconds=null;
  user.pending_duration_label=null;

  user.awaiting='video_duration';

  reply=durationMenu(
`✅ تم حفظ الموضوع:
${text}

`
  );


// ========================================================
// AUTO VIDEO DURATION
// ========================================================

} else if (
  !command &&
  user.awaiting === 'video_duration' &&
  text
) {

  if (text.trim() === '6') {

    user.awaiting='video_duration_custom';

    reply=
`⏱ أرسل المدة المطلوبة بالثواني.

الحد الأدنى: 15 ثانية
الحد الأعلى: 300 ثانية

مثال:
75`;

  } else {

    const duration=
      resolveDuration(text);

    if (!duration) {

      reply=durationMenu(
`❌ اختيار المدة غير صحيح.

`
      );

    } else {

      user.pending_duration_seconds=
        duration.seconds;

      user.pending_duration_label=
        duration.label;

      user.awaiting='video_style';

      reply=styleMenu(
`✅ مدة الفيديو:
${duration.label}

`
      );
    }
  }

} else if (
  !command &&
  user.awaiting === 'video_duration_custom' &&
  text
) {

  const seconds=
    parseCustomDuration(text);

  if (!seconds) {

    reply=
`❌ المدة غير صحيحة.

أرسل رقمًا بين 15 و300 ثانية.`;

  } else {

    user.pending_duration_seconds=seconds;
    user.pending_duration_label=
      `${seconds} ثانية`;

    user.awaiting='video_style';

    reply=styleMenu(
`✅ مدة الفيديو:
${seconds} ثانية

`
    );
  }


// ========================================================
// AUTO VIDEO STYLE
// ========================================================

} else if (
  !command &&
  user.awaiting === 'video_style' &&
  text
) {

  const selected=
    resolveStyle(text);

  if (!selected) {

    reply=styleMenu(
`❌ الاختيار غير صحيح.

`
    );

  } else {

    videoSubject=String(
      user.pending_topic || ''
    ).trim();

    visualStyle=selected.key;
    visualStyleLabel=selected.label;

    targetDurationSeconds=
      Number(
        user.pending_duration_seconds || 0
      );

    targetDurationLabel=
      user.pending_duration_label
      || 'تلقائي';

    user.awaiting=null;
    user.pending_topic=null;
    user.pending_duration_seconds=null;
    user.pending_duration_label=null;
    user.pending_style=null;

    route='video';
    scriptMode='auto';

    reply=
`⏳ تم استلام الطلب.

🎬 الموضوع:
${videoSubject}

⏱ المدة:
${targetDurationLabel}

🎨 نمط المشاهد:
${visualStyleLabel}

جاري تجهيز الفيديو...`;
  }


// ========================================================
// STATUS / HISTORY / SETTINGS / CANCEL
// ========================================================

} else if (command === '/status') {

  const job=store.jobs.find(
    j => String(j.telegram_id) === telegramId
  );

  if (!job) {

    reply='📊 لا توجد لديك مهمة محفوظة حتى الآن.';

  } else {

    route='status';
    taskId=job.task_id;
  }

} else if (command === '/history') {

  const jobs=store.jobs
    .filter(
      j => String(j.telegram_id) === telegramId
    )
    .slice(0,5);

  if (!jobs.length) {

    reply='📚 السجل فارغ.';

  } else {

    reply=
      '📚 آخر المهام\n\n' +
      jobs.map(
        (j,i) =>
`${i+1}. ${j.title || j.topic}
${j.task_id}
${j.status}`
      ).join('\n\n');
  }

} else if (command === '/settings') {

  reply=
`⚙️ الإعدادات الحالية

اللغة: ${user.language}
الصوت: ${user.voice}
المقاس: ${user.video_aspect}

⏱ مدة الفيديو:
يتم اختيارها لكل فيديو

🎨 نمط المشاهد:
يتم اختياره لكل فيديو`;

} else if (command === '/cancel') {

  user.awaiting=null;

  user.pending_title=null;
  user.pending_topic=null;
  user.pending_duration_seconds=null;
  user.pending_duration_label=null;
  user.pending_style=null;
  user.pending_materials=[];

  reply='❌ تم إلغاء أي طلب إدخال غير مكتمل.';

} else {

  reply=
`الأمر غير معروف.

استخدم /start لعرض الأوامر.`;
}


// ========================================================
// MATERIALS FOR VIDEO TASK
// ========================================================

if (route === 'video') {

  supplementalMaterials=
    Array.isArray(user.pending_materials)
      ? [...user.pending_materials]
      : [];
}


// ========================================================
// OUTPUT
// ========================================================

return [{
  json:{
    chat_id:chatId,
    telegram_id:telegramId,
    username:user.username,

    command,
    route,
    task_id:taskId,

    video_title:videoTitle,
    video_subject:videoSubject,
    video_script:videoScript,

    script_mode:scriptMode,

    visual_style:visualStyle,
    visual_style_label:visualStyleLabel,

    target_duration_seconds:
      targetDurationSeconds,

    target_duration_label:
      targetDurationLabel,

    video_language:user.language,
    voice_name:user.voice,
    video_aspect:user.video_aspect,

    material_file_id:materialFileId,
    material_extension:materialExtension,
    material_mime_type:materialMimeType,

    supplemental_materials:
      supplementalMaterials,

    supplemental_materials_count:
      supplementalMaterials.length,

    reply
  }
}];

if ($json.route !== 'video' || !$json.video_subject) {
  return [];
}

return items;

const ctxItems = $items('Attach User Materials');
const ctx = ctxItems.length ? ctxItems[0].json : {};

const taskId = $json?.data?.task_id;

if (!taskId) {
  return [{
    json: {
      chat_id: ctx.chat_id,
      task_reply:
`❌ لم يتم إنشاء المهمة في MoneyPrinterTurbo.

الاستجابة:
${JSON.stringify($json)}`
    }
  }];
}

const store = $getWorkflowStaticData('global');

if (!store.jobs) {
  store.jobs = [];
}

const job = {
  telegram_id: String(ctx.telegram_id),
  chat_id: ctx.chat_id,
  task_id: taskId,
  title: ctx.video_title || ctx.video_subject,
  topic: ctx.video_subject,
  status: 'submitted',
  progress: 0,
  created_at: new Date().toISOString()
};

store.jobs.unshift(job);

const userKey=String(ctx.telegram_id);

if (store.users?.[userKey]) {
  store.users[userKey].pending_materials=[];
}


