function normalizeWords(text) {
  return String(text || '')
    .replace(/[،,؛;:()"']/g,' ')
    .replace(/\s+/g,' ')
    .trim();
}

function compactScene(text) {

  const normalized=
    normalizeWords(text);

  if (!normalized) {
    return '';
  }

  const words=
    normalized.split(/\s+/);

  const meaningful=
    words.filter(
      word =>
        word.length > 1 &&
        !stopWords.has(word)
    );

  const chosen=
    meaningful.length >= 3
      ? meaningful
      : words;

  return chosen
    .slice(0,5)
    .join(' ');
}

function styledTerm(base) {

  const clean=
    compactScene(base);

  if (!clean) {
    return '';
  }

  return suffix
    ? `${clean} ${suffix}`
    : clean;
}

const sceneBases=[];

