      gap >
      30 * 60 * 1000
    ) {
      break;
    }

    latestBatch.unshift(
      candidates[i]
    );

    cursor=
      candidates[i].timestamp;
  }
}


// ========================================================
// Merge:
// 1. Existing staticData materials if available
// 2. Actual files on disk as authoritative fallback
// ========================================================

const merged=[];
const seen=new Set();

const existing=
  Array.isArray(
    ctx.supplemental_materials
  )
    ? ctx.supplemental_materials
    : [];

for (const material of existing) {

  const url=
    String(
      material?.url || ''
    );

  if (
    !url ||
    seen.has(url)
  ) {
    continue;
  }

  seen.add(url);

  merged.push({
    provider:'local',
    url,
    duration:Number(
      material?.duration || 0
    )
  });
}

for (const entry of latestBatch) {

  if (
    seen.has(entry.name)
  ) {
    continue;
  }

  seen.add(
    entry.name
  );

  merged.push({
    provider:'local',
    url:entry.name,
    duration:0
  });
}

ctx.supplemental_materials=
  merged;

ctx.supplemental_materials_count=
  merged.length;

ctx.user_material_files=
  latestBatch.map(
    item => item.name
  );

return [{
  json:ctx
}];
